WITH filtered AS (SELECT *, ROUND(units * 1.07, 2) AS adjusted_units, LEAST(units, revenue) AS least_units_revenue FROM store_sales WHERE sale_date > DATE '2023-08-07'), base AS (SELECT *, least_units_revenue - adjusted_units AS least_units_revenue_minus_adjusted_units, DATEDIFF(CURRENT_DATE(), sale_date) AS days_since_sale_date FROM filtered WHERE revenue > 2000), ranked AS (SELECT id, store_id, units, least_units_revenue, least_units_revenue_minus_adjusted_units, days_since_sale_date FROM base QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY least_units_revenue_minus_adjusted_units NULLS FIRST, id) = 1), with_windows AS (SELECT *, AVG(units) OVER (PARTITION BY store_id) AS store_id_avg_units, LEAD(days_since_sale_date, 1) OVER (PARTITION BY store_id ORDER BY least_units_revenue, id) AS next_days_since_sale_date, NTILE(4) OVER (PARTITION BY store_id ORDER BY least_units_revenue DESC, id) AS least_units_revenue_bucket, AVG(least_units_revenue) OVER w_ordered AS least_units_revenue_avg_6_prior, SUM(least_units_revenue_minus_adjusted_units) OVER (PARTITION BY store_id ORDER BY days_since_sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_least_units_revenue_minus_adjusted_units FROM ranked WINDOW w_ordered AS (PARTITION BY store_id ORDER BY units, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING)), valid AS (SELECT *, COALESCE(least_units_revenue_avg_6_prior, 0) AS least_units_revenue_avg_6_prior_filled FROM with_windows WHERE least_units_revenue_minus_adjusted_units >= 27) SELECT id, least_units_revenue_minus_adjusted_units, next_days_since_sale_date FROM valid
